<template><view class="page"><view class="profile-head"><image v-if="avatar" class="avatar large" :src="avatar" mode="aspectFill"/><view v-else class="avatar large">林</view><text class="title">{{nickname}}</text><text class="muted">{{schoolName||'学校未设置'}}</text></view><view class="grid-2 profile-metrics"><view class="metric"><text class="metric-label">累计减碳</text><text class="metric-value">128.6 kg</text></view><view class="metric"><text class="metric-label">累计积分</text><text class="metric-value">{{points}}</text></view></view><view class="menu card"><view v-for="item in menu" :key="item.title" class="menu-row" @tap="open(item.url)"><text class="menu-icon">{{item.icon}}</text><view class="menu-copy"><text>{{item.title}}</text><text v-if="item.title==='个人信息'" class="school-value">{{schoolName||'未设置'}}</text></view><text class="arrow">›</text></view></view><view class="outline-btn logout" @tap="logout">退出当前身份</view><BottomNav active="profile"/></view></template>
<script>import BottomNav from '../../components/BottomNav.vue';import {identityKey} from '../../common/mock.js';export default{components:{BottomNav},data(){return{avatar:'',nickname:'林间漫步者',schoolName:'',points:1280,menu:[{icon:'⌂',title:'个人信息',url:'/pages/personal/personal-info'},{icon:'▥',title:'排名分析',url:'/pages/personal/rank'},{icon:'◇',title:'我的兑换',url:'/pages/personal/orders'},{icon:'⚙',title:'账号设置',url:'/pages/personal/settings'}]}},onShow(){this.avatar=uni.getStorageSync('user_avatar')||'';this.nickname=uni.getStorageSync('user_nickname')||'林间漫步者';this.schoolName=uni.getStorageSync('user_school_name')||'';this.points=Number(uni.getStorageSync('user_points')||1280)},methods:{open(url){uni.navigateTo({url})},logout(){uni.removeStorageSync(identityKey);uni.removeStorageSync('user_session');uni.reLaunch({url:'/pages/login/login'})}}}</script>
<style lang="scss">@import '../../common/portal.scss';.profile-head{padding:38rpx 0;text-align:center}.avatar{display:flex;align-items:center;justify-content:center;border-radius:50%;background:#d6e6e3;color:#006d37}.avatar.large{width:150rpx;height:150rpx;margin:0 auto 22rpx;font-size:58rpx}.profile-head .title{display:block;font-size:40rpx}.profile-head .muted{display:block;margin-top:10rpx}.menu{margin-top:28rpx;padding:0}.menu-row{display:flex;align-items:center;padding:26rpx 28rpx;border-bottom:1rpx solid #edf1ef;color:#3d4a3f;font-size:27rpx}.menu-icon{width:52rpx;color:#006d37;font-size:30rpx}.menu-copy{display:flex;flex:1;align-items:center;justify-content:space-between}.school-value{margin-right:12rpx;color:#7c8981;font-size:22rpx}.arrow{color:#9aa69f;font-size:38rpx}.logout{margin-top:30rpx}</style>
